recipes.code:
{
  "inputs": [
    {
      "id": "dungbeetle-agent-token",
      "type": "promptString",
      "description": "Scoped, revocable agent token minted via `dungbeetle login` (recommended).",
      "password": true
    },
    {
      "id": "dungbeetle-client-secret",
      "type": "promptString",
      "description": "Repository client secret (pairs with DUNGBEETLE_CLIENT_ID).",
      "password": true
    }
  ],
  "servers": {
    "mcp": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "dungbeetle-mcp@0.1.0"
      ],
      "env": {
        "DUNGBEETLE_AGENT_TOKEN": "${input:dungbeetle-agent-token}",
        "DUNGBEETLE_CLIENT_ID": "<dungbeetle-client-id>",
        "DUNGBEETLE_CLIENT_SECRET": "${input:dungbeetle-client-secret}",
        "DUNGBEETLE_SERVER_URL": "<dungbeetle-server-url>"
      }
    }
  }
}
